using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;

namespace ListenerNET6
{
	internal class Program
	{
		static void Main(string[] args)
		{

			Socket oSocket = new Socket(AddressFamily.InterNetwork, SocketType.Dgram, ProtocolType.Udp);

			// Allows more than one instance to bind to port and receive messages
			oSocket.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.ReuseAddress, 1);

			IPEndPoint oEndPoint = new IPEndPoint(IPAddress.Any, 7560);

			oSocket.Bind(oEndPoint);

			EndPoint oSourceEndPoint = oEndPoint;



			while (true)
			{


				int iAvailable = oSocket.ReceiveBufferSize;

				byte[] bytaData = new byte[iAvailable];

				IAsyncResult oReceiveResult = oSocket.BeginReceiveMessageFrom(bytaData, 0, iAvailable, SocketFlags.None, ref oSourceEndPoint, null, null);

				WaitHandle.WaitAny(new WaitHandle[] { oReceiveResult.AsyncWaitHandle });

				SocketFlags enumSocketFlags = SocketFlags.None;
				IPPacketInformation oIpPacketInformation;

				int iReceivedCount = oSocket.EndReceiveMessageFrom(
					asyncResult: oReceiveResult, socketFlags: ref enumSocketFlags, endPoint: ref oSourceEndPoint, ipPacketInformation: out oIpPacketInformation);



				string sMessage = Encoding.UTF8.GetString(bytaData, 0, iReceivedCount);

				Console.WriteLine($"Received - {sMessage} - Flags {enumSocketFlags}");

			}
		}
	}
}
