using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;

namespace SenderNET6
{
	internal class Program
	{
		static void Main(string[] args)
		{
			

			while (true)
			{

				IPEndPoint oEndPoint = new IPEndPoint(IPAddress.Broadcast, 7560); //Using Port 7560


				StringBuilder sbMessage = new StringBuilder();

				sbMessage.Append(DateTime.Now.ToLongDateString());
				sbMessage.Append(" - ");
				sbMessage.Append(DateTime.Now.ToLongTimeString());

				UdpClient oClient = new UdpClient();

				byte[] bytaData = Encoding.UTF8.GetBytes(sbMessage.ToString());

				if (bytaData.Length > oClient.Client.SendBufferSize)
				{
					// Attempt to send more data than default size of UDP clients send buffer.  If you increase
					// this you will also need to increase the receiving sockets buffer, in ReadMessage or
					// else messages will be truncated.
					// But if broadcast messages are getting too long, you are probably doing it wrong...
					throw new ArgumentOutOfRangeException($"Message length ({bytaData.Length}) exceeds default size of UDP Client buffer ({oClient.Client.SendBufferSize})");
				}

				oClient.Send(bytaData, bytaData.Length, oEndPoint);
				oClient.Close();

				Console.WriteLine($"Send - {sbMessage.ToString()}");

				Thread.Sleep(5000); //Wait 5 seconds
			}

		}
	}
}
